"use client";

import { createContext, useContext, useEffect, useState } from "react";
import { useRouter } from "next/navigation";

type TipoUsuario = "doador" | "beneficiario" | null;

interface AuthData {
  email: string;
  tipo: TipoUsuario;
  logado: boolean;
}

interface AuthContextType {
  auth: AuthData | null;
  login: (email: string, senha: string, tipo: TipoUsuario) => boolean;
  logout: () => void;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType>({} as AuthContextType);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [auth, setAuth] = useState<AuthData | null>(null);
  const router = useRouter();

  useEffect(() => {
    const authSalvo = localStorage.getItem("auth");
    if (authSalvo) {
      setAuth(JSON.parse(authSalvo));
    }
  }, []);

  function login(email: string, senha: string, tipo: TipoUsuario) {
    // ⚠️ aqui entra sua validação real
    if (!email || !senha || !tipo) return false;

    const authData: AuthData = {
      email,
      tipo,
      logado: true,
    };

    localStorage.setItem("auth", JSON.stringify(authData));
    setAuth(authData);

    return true;
  }

  function logout() {
    localStorage.removeItem("auth");
    setAuth(null);
    router.push("/login");
  }

  return (
    <AuthContext.Provider
      value={{
        auth,
        login,
        logout,
        isAuthenticated: !!auth?.logado,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
